# Nouveau logo Baobab dans baobab-administration
# À lancer depuis le dossier baobab-administration (celui qui contient package.json) :
#     powershell -ExecutionPolicy Bypass -File .\installer_logo_administration.ps1
# Les fichiers existants sont sauvegardés en .bak avant d'être remplacés.
$ErrorActionPreference = "Stop"

if (-not (Test-Path "package.json")) {
    throw "Lancez ce script depuis le dossier baobab-administration (celui qui contient package.json)."
}
$root = (Get-Location).Path
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Write-ProjectFile([string]$relative, [string]$content) {
    $full = Join-Path $root $relative
    $dir = Split-Path $full -Parent
    New-Item -ItemType Directory -Force $dir | Out-Null
    $status = "créé      : "
    if (Test-Path $full) {
        $current = [System.IO.File]::ReadAllText($full)
        if ($current.Replace("`r`n", "`n") -eq $content.Replace("`r`n", "`n")) {
            Write-Host ("déjà fait : " + $relative)
            return
        }
        Copy-Item $full ($full + ".bak") -Force
        $status = "remplacé  : "
    }
    [System.IO.File]::WriteAllText($full, $content, $utf8)
    Write-Host ($status + $relative)
}

function Write-ProjectBinary([string]$relative, [string]$base64) {
    $full = Join-Path $root $relative
    New-Item -ItemType Directory -Force (Split-Path $full -Parent) | Out-Null
    [System.IO.File]::WriteAllBytes($full, [System.Convert]::FromBase64String($base64))
    Write-Host ("écrit     : " + $relative)
}

Write-ProjectBinary "public\logo.png" ""

Write-ProjectBinary "public\favicon.png" ""

